import{c as a,$ as e,Q as o,j as n,g as s,o as r,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const b=JSON.parse('{"title":"Производственный цикл","description":"Сквозное пошаговое руководство по производственному конвейеру мастерской в ОмниКрафт ЕРП — от закупки сырья и калькулятора до верстака, склада готовых изделий и розничных продаж.","frontmatter":{"title":"Производственный цикл","description":"Сквозное пошаговое руководство по производственному конвейеру мастерской в ОмниКрафт ЕРП — от закупки сырья и калькулятора до верстака, склада готовых изделий и розничных продаж.","datePublished":"2026-11-15","dateModified":"2026-11-15","order":6},"headers":[],"relativePath":"ru/docs/spaces/production/cycle.md","filePath":"ru/docs/spaces/production/cycle.md","lastUpdated":1794700800000}'),c={name:"ru/docs/spaces/production/cycle.md"},g={id:"производственныи-цикл-пошаговое-руководство-мастера",tabindex:"-1"};function p(h,t,m,u,f,x){const l=e("DocIcon");return o(),n("div",null,[s("h1",g,[r(l,{name:"workflow"}),t[0]||(t[0]=i(" Производственный цикл: Пошаговое руководство мастера ",-1)),t[1]||(t[1]=s("a",{class:"header-anchor",href:"#производственныи-цикл-пошаговое-руководство-мастера","aria-label":'Permalink to "Производственный цикл: Пошаговое руководство мастера"'},"​",-1))]),t[2]||(t[2]=d('<p>В ремесленном и производственном деле успех определяет не столько скорость работы руками, сколько жесткая связность технологических и финансовых этапов. Когда закупки ведутся в блокноте, рецепты хранятся в голове, остатки считаются «на глаз», а выручка сразу тратится из кармана — мастер неизбежно сталкивается с кассовыми разрывами и мнимой прибылью.</p><p>В <strong>ОмниКрафт ЕРП</strong> производственный процесс организован как строгий сквозной конвейер. Каждый физический шаг в мастерской моментально отражается в учете: закупка формирует себестоимость сырья, рецепт рассчитывает трудозатраты, верстак списывает материалы, а касса фиксирует чистую прибыль сделки.</p><hr><h2 id="сквознои-физическии-пример-мастерскои" tabindex="-1">Сквозной физический пример мастерской <a class="header-anchor" href="#сквознои-физическии-пример-мастерскои" aria-label="Permalink to &quot;Сквозной физический пример мастерской&quot;">​</a></h2><p>Чтобы увидеть работу конвейера в реальных цифрах, пройдем полный производственный маршрут на примере классического ремесленного изделия: <strong>«Кошелек-бифолд из шорно-седельной кожи»</strong>:</p><ul><li><strong>Сырьевой состав:</strong> натуральная кожа растительного дубления (12,5 кв. дм), вощеная плетеная нить (4 м), аппретура и защитный воск.</li><li><strong>Трудозатраты:</strong> 2,5 часа чистого времени квалифицированного мастера при базовой ставке 800 рублей в час.</li><li><strong>Накладные расходы:</strong> амортизация швейного и ручного инструмента, аренда помещения и электричество.</li><li><strong>Упаковка:</strong> жесткая крафтовая коробка, тишью и бирка из плотного картона.</li><li><strong>Партия выпуска:</strong> 5 готовых изделий на верстаке.</li></ul><hr><h2 id="шаг-1-приемка-сырья-на-склад" tabindex="-1">Шаг 1. Приемка сырья на склад <a class="header-anchor" href="#шаг-1-приемка-сырья-на-склад" aria-label="Permalink to &quot;Шаг 1. Приемка сырья на склад&quot;">​</a></h2><p>Любое изделие начинается с закупки материалов. Прежде чем раскроить первую деталь, сырье необходимо поставить на баланс.</p><p>Перейдите во вкладку <strong>«Материалы»</strong> (Склад) и нажмите кнопку <strong>«Партионная закупка сырья»</strong>:</p><ol><li><strong>Заполнение позиций накладной:</strong> Укажите наименование материала, количество и цену закупки от поставщика.</li><li><strong>Учет сопутствующей доставки:</strong> Если за доставку партии курьерской службой Вы заплатили 500 рублей, внесите эту сумму в поле «Стоимость доставки». Программа пропорционально распределит логистику по стоимости каждой позиции, включив её в закупочную себестоимость.</li><li><strong>Фиксация оплаты:</strong> При сохранении закупки система автоматически сформирует расходный ордер в кассе (вкладка <strong>«ДДС»</strong>). Вам не требуется дублировать операцию вручную.</li></ol><div class="info custom-block"><p class="custom-block-title">Скользящая средняя стоимость (МАК)</p><p>Если на складе уже лежали остатки кожи по 40 рублей за кв. дм, а новая партия пришла по 50 рублей, программа автоматически рассчитает средневзвешенную цену методом скользящей средней стоимости (МАК). Все последующие списания пойдут по объективной справедливой оценке.</p></div><hr><h2 id="шаг-2-проектирование-технологическои-карты-калькулятор" tabindex="-1">Шаг 2. Проектирование технологической карты (Калькулятор) <a class="header-anchor" href="#шаг-2-проектирование-технологическои-карты-калькулятор" aria-label="Permalink to &quot;Шаг 2. Проектирование технологической карты (Калькулятор)&quot;">​</a></h2><p>Когда материалы оприходованы на складе, необходимо зафиксировать инженерные стандарты изделия. Перейдите во вкладку <strong>«Калькулятор»</strong> в режим <strong>«База рецептов»</strong> и нажмите <strong>«Создать рецепт»</strong>:</p><ol><li><strong>Основные параметры:</strong> Присвойте изделию название (<em>«Кошелек-бифолд (Коньяк)»</em>) и укажите норму времени — <code>2.5</code> часа. Программа умножит это время на Вашу ставку мастера из Настроек (<code>800 руб./ч</code>), заложив <code>2 000 руб.</code> на оплату труда.</li><li><strong>Сырье изделия (Списание на верстаке):</strong> Добавьте материалы из складского наличия: <ul><li>Кожа растительного дубления: <code>12.5</code> кв. дм (по текущей МАК-цене склада <code>45 руб.</code> = <code>562.50 руб.</code>);</li><li>Вощеная нить: <code>4</code> пог. м (по <code>8 руб.</code> = <code>32.00 руб.</code>);</li><li>Аппретура и финишная химия: фиксированная норма <code>65.00 руб.</code>.</li></ul></li><li><strong>Накладные расходы мастерской:</strong> Задайте коэффициенты косвенных затрат. Система включит процент на износ станков и постоянную долю аренды (в нашем примере — <code>215.95 руб.</code>).</li><li><strong>Сборка упаковки (Отложенное списание):</strong> Во вкладке «Упаковка» выберите комплект: крафтовая коробка и полиграфия на сумму <code>180.00 руб.</code>.</li></ol><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Калькуляция изделия</span><div class="formula-heading">Полная себестоимость изготовления на верстаке</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Себестоимость сборки</span><span class="math-op">=</span><span class="math-num">562,50 ₽</span><span class="math-op">+</span><span class="math-num">32,00 ₽</span><span class="math-op">+</span><span class="math-num">65,00 ₽</span><span class="math-op">+</span><span class="math-num">2 000,00 ₽</span><span class="math-op">+</span><span class="math-num">215,95 ₽</span><span class="math-op">=</span><span class="math-result">2 875,45 ₽</span></div></div></div><div class="tip custom-block"><p class="custom-block-title">Совет мастера: Закладка технологического запаса на обрезки</p><p>При раскрое натуральной кожи или сортового дерева неизбежно образуются краевые обрезки и участки с естественными пороками сырья. Не закладывайте в рецепт геометрическую площадь выкроек «впритык». Всегда прибавляйте технологический запас 15–20% к норме расхода материала, чтобы фактическая себестоимость отражала реальный расход шкуры или доски.</p></div><div class="info custom-block"><p class="custom-block-title">Разделение себестоимости сборки и предпродажной упаковки</p><p>Обратите внимание: упаковочные материалы <strong>не списываются при производстве изделия</strong>. Кошелек может храниться на складе месяцами в технической пленке, а покупатель выберет либо простую крафтовую коробку, либо подарочный деревянный бокс. Упаковка бронируется в рецепте для расчета полной цены, но спишется со склада строго в момент продажи.</p></div><hr><h2 id="шаг-3-запуск-партии-на-верстак" tabindex="-1">Шаг 3. Запуск партии на Верстак <a class="header-anchor" href="#шаг-3-запуск-партии-на-верстак" aria-label="Permalink to &quot;Шаг 3. Запуск партии на Верстак&quot;">​</a></h2><p>Когда рецепт утвержден, мастер приступает к раскрою и изготовлению тиража.</p><ol><li>Перейдите во вкладку <strong>«Калькулятор»</strong> в режим <strong>«Расчет тиража»</strong>.</li><li>В строке поиска выберите изделие <em>«Кошелек-бифолд (Коньяк)»</em> и укажите тираж: <code>5</code> штук.</li><li><strong>Проверка обеспеченности сырьем:</strong> Система мгновенно сверит требуемый объем (62,5 кв. дм кожи, 20 м нити) с фактическими складскими остатками. Если сырья достаточно, строка подсветится спокойным зеленым индикатором.</li><li>Нажмите кнопку <strong>«Запустить в производство»</strong>. Партия отправится в работу, зарезервировав сырье на складе.</li></ol><hr><h2 id="шаг-4-выпуск-продукции-на-склад-готовых-изделии" tabindex="-1">Шаг 4. Выпуск продукции на склад готовых изделий <a class="header-anchor" href="#шаг-4-выпуск-продукции-на-склад-готовых-изделии" aria-label="Permalink to &quot;Шаг 4. Выпуск продукции на склад готовых изделий&quot;">​</a></h2><p>Вкладка <strong>«Верстак»</strong> служит цифровым диспетчером Вашей мастерской. Здесь отображаются все партии, находящиеся в раскрое, склейке, прошивке или финишной обработке.</p><p>Когда все 5 кошельков собраны, прошиты и прошли контроль качества:</p><ol><li>Найдите партию в списке на верстаке и нажмите кнопку <strong>«Выпустить партию»</strong>.</li><li><strong>Что происходит под капотом программы:</strong><ul><li>Со склада сырья безвозвратно списываются 62,5 кв. дм кожи, 20 м нити и химия по их фактической МАК-стоимости на момент запуска;</li><li>На склад готовой продукции (вкладка <strong>«Товары»</strong>) приходуются 5 единиц кошельков с точной производственной себестоимостью <code>2 875.45 руб.</code> за штуку;</li><li>Партия на верстаке закрывается и переходит в архив выполненных работ.</li></ul></li></ol><div class="warning custom-block"><p class="custom-block-title">Технологический сбой: Что делать при браке заготовки</p><p>Если в процессе сборки одна заготовка была испорчена и мастер взял со склада дополнительный кусок кожи, оформите ручное списание испорченного материала во вкладке «Материалы» с причиной <em>«Технологический брак»</em>. Это сохранит идеальную точность складских остатков и не исказит плановую себестоимость партии.</p></div><hr><h2 id="шаг-5-оформление-розничнои-продажи" tabindex="-1">Шаг 5. Оформление розничной продажи <a class="header-anchor" href="#шаг-5-оформление-розничнои-продажи" aria-label="Permalink to &quot;Шаг 5. Оформление розничной продажи&quot;">​</a></h2><p>Готовые изделия поступили на баланс и готовы к передаче покупателю через мастерскую или онлайн-витрину.</p><p>Перейдите во вкладку <strong>«Продажи»</strong> и нажмите <strong>«Новая продажа»</strong>:</p><ol><li><strong>Выбор товара:</strong> Выберите из каталога <em>«Кошелек-бифолд (Коньяк)»</em>. Программа автоматически спишет единицу со склада по методу первых партий (ФИФО).</li><li><strong>Выбор упаковки:</strong> Укажите комплект упаковки (крафтовая коробка). В эту же секунду коробка спишется с материального склада.</li><li><strong>Розничная цена:</strong> Программа подставит рекомендованную цену с учетом торговой наценки 60% — <code>4 900 руб.</code> (при необходимости Вы можете скорректировать цену вручную или применить скидку).</li><li><strong>Способ оплаты:</strong> Выберите наличный расчет или безналичный перевод на счет.</li><li>Нажмите <strong>«Завершить продажу»</strong>. Чек сформирован, товар отгружен клиенту.</li></ol><hr><h2 id="шаг-6-финансовыи-результат-и-замыкание-контура" tabindex="-1">Шаг 6. Финансовый результат и замыкание контура <a class="header-anchor" href="#шаг-6-финансовыи-результат-и-замыкание-контура" aria-label="Permalink to &quot;Шаг 6. Финансовый результат и замыкание контура&quot;">​</a></h2><p>Сразу после проведения продажи в системе происходит мгновенная финансовая проводка:</p><ul><li><strong>Касса (ДДС):</strong> Появляется доходная запись на сумму <code>+4 900 руб.</code> с привязкой к номеру чека.</li><li><strong>Прибыль сделки:</strong> Программа вычитает из розничной цены производственную себестоимость изделия (<code>2 875.45 руб.</code>) и стоимость упаковки (<code>180.00 руб.</code>), фиксируя чистую коммерческую прибыль:</li></ul><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Финансовый итог</span><div class="formula-heading">Чистая коммерческая прибыль со сделки</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Чистая прибыль</span><span class="math-op">=</span><span class="math-num">4 900,00 ₽</span><span class="math-op">−</span><span class="math-num">2 875,45 ₽</span><span class="math-op">−</span><span class="math-num">180,00 ₽</span><span class="math-op">=</span><span class="math-result">1 844,55 ₽</span></div></div></div><ul><li><strong>Аналитика:</strong> Обновляются графики выручки, показатель среднего чека и точка безубыточности.</li><li><strong>Управленческий баланс (Капитал):</strong> Стоимость склада готовой продукции уменьшилась на себестоимость кошелька, а остаток денег в кассе вырос на полную сумму продажи. Собственный капитал мастера увеличился ровно на величину заработанной чистой прибыли.</li></ul><hr><h2 id="сводная-матрица-движения-ресурсов-по-этапам-конвеиера" tabindex="-1">Сводная матрица движения ресурсов по этапам конвейера <a class="header-anchor" href="#сводная-матрица-движения-ресурсов-по-этапам-конвеиера" aria-label="Permalink to &quot;Сводная матрица движения ресурсов по этапам конвейера&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Этап конвейера</th><th style="text-align:left;">Вкладка программы</th><th style="text-align:left;">Движение сырья и склада</th><th style="text-align:left;">Движение денег (ДДС)</th><th style="text-align:left;">Экономический результат</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Закупка сырья</strong></td><td style="text-align:left;">Материалы</td><td style="text-align:left;">Приход материалов, расчет МАК-цены</td><td style="text-align:left;">Расход средств из кассы</td><td style="text-align:left;">Деньги перешли в ликвидное сырье</td></tr><tr><td style="text-align:left;"><strong>2. Проектирование</strong></td><td style="text-align:left;">Калькулятор</td><td style="text-align:left;">Расчет норм и трудозатрат</td><td style="text-align:left;">Денежных проводок нет</td><td style="text-align:left;">Определен порог безубыточности</td></tr><tr><td style="text-align:left;"><strong>3. Запуск партии</strong></td><td style="text-align:left;">Верстак</td><td style="text-align:left;">Резервирование сырья под тираж</td><td style="text-align:left;">Денежных проводок нет</td><td style="text-align:left;">Зафиксирован план выпуска партии</td></tr><tr><td style="text-align:left;"><strong>4. Выпуск изделий</strong></td><td style="text-align:left;">Верстак ➔ Товары</td><td style="text-align:left;">Списание сырья, приход готовых товаров</td><td style="text-align:left;">Денежных проводок нет</td><td style="text-align:left;">Сырье трансформировалось в товар</td></tr><tr><td style="text-align:left;"><strong>5. Продажа изделия</strong></td><td style="text-align:left;">Продажи</td><td style="text-align:left;">Списание готового изделия (ФИФО) и тары</td><td style="text-align:left;">Приход выручки в кассу</td><td style="text-align:left;">Товар отгружен клиенту</td></tr><tr><td style="text-align:left;"><strong>6. Итог сделки</strong></td><td style="text-align:left;">Аналитика / Капитал</td><td style="text-align:left;">Актуализация остатков на балансе</td><td style="text-align:left;">Положительное сальдо кассы</td><td style="text-align:left;">Фиксация чистой маржи и рост капитала</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Регулярность цехового цикла</p><p>Сквозной конвейер работает эффективно только при своевременном отражении операций. Заносите закупки сырья в день их доставки, а завершенные партии выпускайте с верстака сразу после проверки ОТК. Это исключает пересортицу на складе и гарантирует 100% достоверность управленческих отчетов.</p></div>',44))])}const v=a(c,[["render",p]]);export{b as __pageData,v as default};
